import {
  CREATE_MANUFACTURER,
  GET_MANUFACTURERS,
  SEARCH_MANUFACTURERS,
  UPDATE_MANUFACTURER,
} from "./constants";
import { tokenConfig } from "../../auth/tokenConfig";
import { all, call, fork, put, takeEvery } from "redux-saga/effects";
import axios from "axios";
import {
  getManufacturersFailed,
  getManufacturersSuccess,
  createManufacturerSuccess,
  createManufacturerFailed,
  updateManufacturerSuccess,
  updateManufacturerFailed,
  searchManufacturerFailed,
  searchManufacturerSuccess,
} from "./actions";

//Get facilities
function* getManufacturers() {
  const apiCall = () => {
    return axios
      .get("users/entities/manufacturers", tokenConfig())
      .then((response) => response.data)
      .catch((err) => {
        throw err;
      });
  };

  try {
    const response = yield call(apiCall);
    console.log("Manufacturers", response);
    yield put(getManufacturersSuccess(response));
  } catch (error) {
    let message;

    console.log("ERRORS", error.response);
    switch (error.status) {
      case 500:
        message = "Internal Server Error";
        break;
      case 401:
        message = "Invalid credentials";
        break;
      default:
        message = error;
    }
    yield put(getManufacturersFailed(message, error.response.data.errors));
  }
}

//Create body system
function* createManufacturer(payload) {
  const apiCall = () => {
    return axios
      .post("entities/manufacturers/create", payload.payload, tokenConfig())
      .then((response) => response.data)
      .catch((err) => {
        throw err;
      });
  };

  try {
    const response = yield call(apiCall);
    console.log("Create Manufacturer: ", response);
    yield put(createManufacturerSuccess(response));
  } catch (error) {
    let message;

    console.log("ERRORS", error.response);
    switch (error.status) {
      case 500:
        message = "Internal Server Error";
        break;
      case 401:
        message = "Invalid credentials";
        break;
      default:
        message = error;
    }
    yield put(createManufacturerFailed(message, error.response.data.errors));
  }
}

//Update body system
function* updateManufacturer(payload) {
  console.log("Update", payload.payload.data);

  const data = JSON.stringify(payload.payload.data);

  const apiCall = () => {
    return axios
      .put(
        `entities/manufacturers/${payload.payload.id}/update`,
        data,
        tokenConfig()
      )
      .then((response) => response.data)
      .catch((err) => {
        throw err;
      });
  };

  try {
    const response = yield call(apiCall);
    console.log("Updated Manufacturer: ", response);
    yield put(updateManufacturerSuccess(response));
  } catch (error) {
    let message;

    console.log("ERRORS", error.response);
    switch (error.status) {
      case 500:
        message = "Internal Server Error";
        break;
      case 401:
        message = "Invalid credentials";
        break;
      default:
        message = error.response.data.detail;
    }
    yield put(updateManufacturerFailed(message, error.response.data.errors));
  }
}

//search distributor
function* searchManufacturer(payload) {
  const apiCall = () => {
    return axios
      .get(`entities/manufacturers?q=${payload.payload}`, tokenConfig())
      .then((response) => response.data)
      .catch((err) => {
        throw err;
      });
  };

  try {
    const response = yield call(apiCall);
    console.log("dddhhd", response);
    yield put(searchManufacturerSuccess(response));
  } catch (error) {
    let message;

    console.log("ERRORS", error.response);
    switch (error.status) {
      case 500:
        message = "Internal Server Error";
        break;
      case 401:
        message = "Invalid credentials";
        break;
      default:
        message = error;
    }
    yield put(searchManufacturerFailed(message, error.response.data.errors));
  }
}

//Get body systems
export function* watchGetManufacturers() {
  yield takeEvery(GET_MANUFACTURERS, getManufacturers);
}

//Add body system
export function* watchAddManufacturer() {
  yield takeEvery(CREATE_MANUFACTURER, createManufacturer);
}

//Update body system
export function* watchUpdateManufacturer() {
  yield takeEvery(UPDATE_MANUFACTURER, updateManufacturer);
}

//Search manufacturers
export function* watchSearchManufacturer() {
  yield takeEvery(SEARCH_MANUFACTURERS, searchManufacturer);
}

function* manufacturersSaga() {
  yield all([
    fork(watchGetManufacturers),
    fork(watchAddManufacturer),
    fork(watchSearchManufacturer),
    fork(watchUpdateManufacturer),
  ]);
}

export default manufacturersSaga;
